// 1. Extract the text from the nested Gemini response structure
const geminiOutput = $input.first().json;
let sql = (
  geminiOutput.content?.parts?.[0]?.text || 
  geminiOutput.text || 
  ''
).replace(/```sql|```/gi, '').trim();

// 2. Validate read-only SELECT intent
if (!/^SELECT\b/i.test(sql) || /;\s*(DROP|DELETE|UPDATE|INSERT|ALTER|TRUNCATE)/i.test(sql)) {
  throw new Error("Only SELECT queries are allowed.");
}

// 3. Get user ID using .first()
const userId = $('Sub-Query Entry').first().json.message.from.id;

// 4. Inject dynamic user isolation view
const executableSql = `
  WITH my_expenses AS (
    SELECT * FROM transactions WHERE telegram_id = ${userId}
  )
  ${sql}
`;

return [{ json: { sql: executableSql } }];

